  "It has no shade": "/audio/production/en-US/comprehension/629f2037880d28c64b4f.mp3",
  "It is covered in sand": "/audio/production/en-US/comprehension/4afeb315cfe949ab82ef.mp3",
  "What does Socks bring out instead of the ball?": "/audio/production/en-US/comprehension/363e85f96bc68b2fdccd.mp3",
  "A puzzle": "/audio/production/en-US/comprehension/db0903d8706faf7eee49.mp3",
