  "A paint box": "/audio/production/en-US/comprehension/da4f0019aa4b17921c25.mp3",
  "A story book": "/audio/production/en-US/comprehension/c778de06c71d8cb62457.mp3",
  "When can they play with the ball outside?": "/audio/production/en-US/comprehension/222ab55ffea0d0009ed3.mp3",
  "When the grass is dry": "/audio/production/en-US/comprehension/c264bcc6f5332248dd25.mp3",
  "While it is raining": "/audio/production/en-US/comprehension/afe4ee3207eeb8771fcf.mp3",
