  "A dry napkin": "/audio/production/en-US/comprehension/f2909edf17e693b20253.mp3",
  "Why does Chips cover the clay?": "/audio/production/en-US/comprehension/1a172799018c13b3a7f1.mp3",
  "To keep it soft": "/audio/production/en-US/comprehension/1bd93f27e22ec2997fd6.mp3",
  "To make it colder": "/audio/production/en-US/comprehension/771e6eb3b18e42c43ef8.mp3",
